const Button = styled.button`
  background-color: ${props => {
    if (props.danger) return '#f44336';
    if (props.success) return '#4CAF50';
    if (props.primary) return '#2196F3';
    if (props.warning) return '#ff9800';
    return '#f5f5f5';
  }};
  color: ${props => {
    if (props.danger || props.success || props.primary || props.warning) return 'white';
    return '#333';
  }};
  border: 1px solid ${props => {
    if (props.danger) return '#d32f2f';
    if (props.success) return '#388e3c';
    if (props.primary) return '#1976d2';
    if (props.warning) return '#f57c00';
    return '#ddd';
  }};
  padding: 8px 16px;
  border-radius: 4px;
  margin-right: 10px;
  cursor: pointer;
  font-size: 14px;
  
  &:hover {
    background-color: ${props => {
      if (props.danger) return '#d32f2f';
      if (props.success) return '#388e3c';
      if (props.primary) return '#1976d2';
      if (props.warning) return '#f57c00';
      return '#e5e5e5';
    }};
  }
  
  &:disabled {
    background-color: #cccccc;
    border-color: #bbbbbb;
    color: #666666;
    cursor: not-allowed;
  }
`;

